count_per_lcm = L // N + L // M - 2

full_cycles = (K - 1) // count_per_lcm
remaining = K - full_cycles * count_per_lcm

result = full_cycles * L

n, m = 1, 1
for _ in range(remaining):
    while n * N <= m * M:
        if n * N < m * M:
            result += n * N
            n += 1
            break
        n += 1
    else:
        result += m * M
        m += 1

print(result)
